@lru_cache(maxsize=3)
def public_array(name):
    shape=globals()[f'_{name}_SHAPE'];data=globals()[f'_{name}_DATA']
    array=np.frombuffer(zlib.decompress(base64.b85decode(data)),dtype='<f8').reshape(shape)
    array.setflags(write=False)
    return array

def pudding_triangles():
    return public_array('PUDDING')
